import{_t as e,it as t,n,rt as r}from"./chunks/framework.BzA9dy5I.js";var i=JSON.parse(`{"title":"Usar el canvas","description":"","frontmatter":{},"headers":[],"relativePath":"guia/usar-el-flujo.md","filePath":"guia/usar-el-flujo.md"}`),a={name:`guia/usar-el-flujo.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="usar-el-canvas" tabindex="-1">Usar el canvas <a class="header-anchor" href="#usar-el-canvas" aria-label="Permalink to “Usar el canvas”">​</a></h1><p>El chat define el objetivo y realiza el trabajo con sus herramientas. El canvas te permite seguir el proceso y aportar decisiones.</p><h2 id="encuentra-tu-siguiente-tarea" tabindex="-1">Encuentra tu siguiente tarea <a class="header-anchor" href="#encuentra-tu-siguiente-tarea" aria-label="Permalink to “Encuentra tu siguiente tarea”">​</a></h2><p>Selecciona una tarea en la navegación superior y usa <strong>Enfocar tarea</strong>. <strong>Seguir actividad</strong> mantiene cerca el trabajo activo. En Ajustes puedes elegir orientación vertical u horizontal y el tema; los trabajos agrupan pasos que puedes desplegar.</p><table tabindex="0"><thead><tr><th>Señal</th><th>Qué significa</th></tr></thead><tbody><tr><td>Inicio verde</td><td>Punto de partida</td></tr><tr><td>Compuerta amarilla</td><td>Divide o reúne caminos</td></tr><tr><td>Fin rojo</td><td>Cierre del proceso, no necesariamente un error</td></tr><tr><td>Tarea verde</td><td>Completada</td></tr><tr><td>Tarea azul</td><td>Lista para el agente o en ejecución; lee su estado</td></tr><tr><td>Tarea ámbar</td><td>Requiere tu intervención</td></tr><tr><td>Tarea roja</td><td>Fallo o rechazo</td></tr><tr><td>Ruta gris</td><td>Pendiente u omitida, según su trazo</td></tr></tbody></table><p>Las rutas muestran el avance registrado. La animación no garantiza que el agente siga conectado. El movimiento se reduce si así lo configuras en el sistema.</p><h2 id="responde-lo-necesario" tabindex="-1">Responde lo necesario <a class="header-anchor" href="#responde-lo-necesario" aria-label="Permalink to “Responde lo necesario”">​</a></h2><p>Cada formulario debe tener una pregunta concreta. El agente puede usar desplegables, Sí/No, cantidades o texto según el dato. Ninguna elección debe estar aprobada por defecto. La ayuda y los detalles opcionales se despliegan cuando los necesitas.</p><p>En <strong>I/O</strong> ves las entradas y salidas; en <strong>Logs</strong>, resúmenes, acciones y observaciones públicas. Se actualizan cuando el agente envía eventos. No son una grabación automática de todas sus herramientas ni de su razonamiento privado.</p><h2 id="retomar-el-trabajo" tabindex="-1">Retomar el trabajo <a class="header-anchor" href="#retomar-el-trabajo" aria-label="Permalink to “Retomar el trabajo”">​</a></h2><p><strong>Espera al agente</strong> significa que la tarea está habilitada y aún no se ha iniciado. Guardar tu respuesta no ejecuta por sí mismo acciones en otra aplicación.</p><p>Si el chat está esperando mediante la integración, recibe el cambio y puede seguir en el mismo turno. Si terminó su turno, usa <strong>Copiar continuación</strong> en Hyperion y envía el texto en el chat conectado. Incluye el ID del flujo para recuperar la decisión y continuar sin empezar otro proceso.</p><p>Si no avanza, comprueba si está pausado, si falta otra respuesta o si el agente informó un error. Consulta la actividad de la tarea; no vuelvas a aprobar lo mismo ni crees otro flujo para eludir el bloqueo.</p><h2 id="reintentar" tabindex="-1">Reintentar <a class="header-anchor" href="#reintentar" aria-label="Permalink to “Reintentar”">​</a></h2><p>Cuando una tarea falla, revisa su log. Pide al agente reintentar tras corregir la causa. El reintento conserva la evidencia del fallo y permite volver a ejecutar la tarea; no borra el historial ni repite aprobaciones humanas automáticamente.</p><h2 id="cambiar-el-plan" tabindex="-1">Cambiar el plan <a class="header-anchor" href="#cambiar-el-plan" aria-label="Permalink to “Cambiar el plan”">​</a></h2><p>Puedes decir en el chat: «Desde esta fase, necesitamos añadir una revisión». El agente puede revisar el trabajo futuro con una explicación. Hyperion conserva lo ya ejecutado y pausa el plan revisado para tu revisión en el canvas. Cambiar el objetivo no debe reescribir el historial.</p><h2 id="compuertas" tabindex="-1">Compuertas <a class="header-anchor" href="#compuertas" aria-label="Permalink to “Compuertas”">​</a></h2><ul><li><strong>Exclusiva (×):</strong> elige un camino según la respuesta.</li><li><strong>Inclusiva (○):</strong> habilita uno o varios caminos que cumplen la condición.</li><li><strong>Paralela (+):</strong> habilita varios caminos y espera su reunión.</li></ul><p>Que dos tareas estén habilitadas no implica que se ejecuten simultáneamente: depende de las capacidades reales del agente.</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};